
	.text

; KN5000 Sub CPU Boot ROM Disassembly
; Original ROM: kn5000_subcpu_boot.ic30 (128KB)
; Target CPU: TMP94C241F (TLCS-900/H2)
;
; This is the boot ROM for the sub CPU (tone generator controller).
; It initializes hardware, copies interrupt vector trampolines to RAM,
; and enters a main loop that calls the payload at 0x0400.
;
; Memory Map:
;   0x0000-0x00FF  - Special Function Registers (SFR)
;   0x0100-0x01FF  - Extended SFR / Memory Controller
;   0x0400-0x04E0  - Interrupt vector trampolines (copied from ROM at boot)
;   0x0500+        - RAM / Payload data area
;   0x120000       - Inter-CPU Communication Latches (shared with main CPU)
;   0x130000       - Tone generator registers
;   0xFE0000-0xFFFFFF - This boot ROM (128KB, but mostly 0xFF)
;
; Boot sequence:
;   1. Reset vector at 0xFFFEE0 jumps to 0xFF8290
;   2. Initialize SFR registers (ports, timers, DMA, etc.)
;   3. Copy interrupt trampolines from ROM (0xFF8F6C) to RAM (0x0400)
;   4. Enable interrupts
;   5. Call initialization routines
;   6. Enter main loop, waiting for payload ready flag
;   7. Call payload entry point at 0x0400
;
; Actual code starts at 0xFF8000 (file offset 0x18000)


; ==============================================================================
; Constants
; ==============================================================================

.equ PAYLOAD_ENTRY, 0x400	; Entry point of loaded payload
.equ PAYLOAD_LOADED_FLAG, 0x4FE	; Bit 6: payload ready, Bit 7: transfer complete
.equ DMA_SETUP_PARAMS, 0x502	; DMA setup block: src(4), dst(4), count(2)
.equ E1_XFER_PARAMS, 0x50C	; E1 command params: dest_addr(4), count(2)
.equ DMA_XFER_STATE, 0x516	; DMA state machine: 0=idle, 1=single, 2=two-phase
.equ E2_XFER_PARAMS, 0x53E	; E2 command params: src_addr(4), count(2)
.equ STACK_INIT, 0x5A2	; Initial stack pointer
.equ DMA_BURST_CTRL, 0x102	; DMA burst/trigger control register
.equ AUDIO_HW_BASE, 0x100000	; Audio hardware registers (DSP/DAC?)
.equ INTER_CPU_LATCH, 0x120000	; Inter-CPU communication latch
.equ TONE_GEN_BASE, 0x130000	; Tone generator base address

; ==============================================================================
; SFR addresses (directly addressable 0x00-0xFF)
; Based on TMP94C241 datasheet with some variations for this hardware config
; ==============================================================================

; Port Function Control Registers
.equ P0FC, 0x7	; Port 0 Function Control
.equ P1FC, 0xB	; Port 1 Function Control
.equ P2FC, 0xF	; Port 2 Function Control
.equ P7, 0x1C	; Port 7 Data
.equ P7CR, 0x1E	; Port 7 Control
.equ P7FC, 0x1F	; Port 7 Function Control
.equ P8, 0x20	; Port 8 Data (Chip Select/WAIT)
.equ P8CR, 0x22	; Port 8 Control
.equ P8FC, 0x23	; Port 8 Function Control
.equ PA, 0x28	; Port A Data (DRAM signals)
.equ PAFC, 0x2B	; Port A Function Control
.equ PB, 0x2C	; Port B Data (DRAM signals)
.equ PBFC, 0x2F	; Port B Function Control

; Port C (TMP94C241 SFR 0x30; MAME's tmp94c241 SFR table: 0x30 PC, 0x32 PCCR, 0x33 PCFC)
.equ INTTC01, 0x30	; MISNAMED: 0x30 is PORT C, not a timer-interrupt register.  Kept
			; because the symbol has no uses in this file (the code writes 0x30
			; literally); see SERIAL_INIT and DELAY_ROUTINE.

; Inter-CPU Status Register (at 0x34, directly addressable)
; Used for handshaking between main CPU and sub CPU
; Bit 0: Sub CPU ready flag (set when ready, cleared when starting transfer)
; Bit 1: Used by interrupt handler to signal completion
; Bit 2: Checked in InterCPU_RX_Handler to gate command processing
; Bit 4: Main CPU ready flag (polled by sub CPU, set by main CPU)
.equ INTERCPU_STATUS, 0x34

; Port 8 area (legacy names for compatibility)
.equ SC0BUF, 0x34	; Alias for INTERCPU_STATUS
.equ SC0CR, 0x36
.equ SC0MOD, 0x38
.equ SC1BUF, 0x3A
.equ SC1CR, 0x3C
.equ SC1MOD, 0x3E

; Port 8 extended area
.equ P8_DATA, 0x40	; Port 8 extended data
.equ P8_FC_LO, 0x44	; Port 8 function control low
.equ P8_FC_HI, 0x46	; Port 8 function control high
.equ P8_FC_EXT, 0x47	; Port 8 function control extended

; Port E area (Timer/Interrupt signals)
.equ PE_DATA, 0x68	; Port E Data
.equ PE_CR, 0x6A	; Port E Control

; 8-Bit Timer Registers (0x80-0x8F)
.equ T01MOD, 0x80	; Timer 0/1 Mode (NOT watchdog - that's at 110h)
				; Bit 0: PRRUN (Prescaler run)
				; Bit 1-2: T0CLK (Timer 0 clock source)
				; Bit 3-4: T01M (Timer 0/1 mode)
				; Bit 5: PWM0
				; Bit 6-7: T1CLK (Timer 1 clock source)
.equ T01FFCR, 0x81	; Timer 0/1 Flip-Flop Control
.equ T8RUN, 0x82	; 8-bit Timer Run Control (T0RUN, T1RUN, T2RUN, T3RUN)
.equ TRDC, 0x83	; Timer Register Double-buffer Control
.equ TREG0, 0x84	; Timer 0 Register (write-only)
.equ TREG1, 0x85	; Timer 1 Register (write-only)
.equ T23MOD, 0x88	; Timer 2/3 Mode
.equ T23FFCR, 0x89	; Timer 2/3 Flip-Flop Control
.equ TREG2, 0x8A	; Timer 2 Register (write-only)
.equ TREG3, 0x8B	; Timer 3 Register (write-only)

; Legacy aliases for backward compatibility with existing code
.equ WDMOD, 0x80	; Legacy alias - actually T01MOD, not watchdog!
.equ WDCR, 0x81	; Legacy alias - actually T01FFCR
.equ REG_40, 0x40	; = P8_DATA
.equ REG_44, 0x44	; = P8_FC_LO
.equ REG_46, 0x46	; = P8_FC_HI
.equ REG_47, 0x47	; = P8_FC_EXT
.equ REG_68, 0x68	; = PE_DATA
.equ REG_6A, 0x6A	; = PE_CR

; 16-Bit Timer 4 Registers (0x98-0x9F)
.equ T4MOD, 0x98	; Timer 4 Mode
.equ T4FFCR, 0x99	; Timer 4 Flip-Flop Control
.equ CAP4L, 0x9E	; Timer 4 Capture Low
.equ CAP4H, 0x9F	; Timer 4 Capture High

; Serial Channel 0 Registers (0xD0-0xD3)
.equ SER0_BUF, 0xD0	; Serial 0 Buffer (TX/RX)
.equ SER0_CR, 0xD1	; Serial 0 Control
.equ SER0_MOD, 0xD2	; Serial 0 Mode
.equ SER0_BAUD, 0xD3	; Serial 0 Baud Rate Control

; Serial Channel 1 Registers (0xD4-0xD7)
.equ SER1_BUF, 0xD4	; Serial 1 Buffer (TX/RX)
.equ SER1_CR, 0xD5	; Serial 1 Control
.equ SER1_MOD, 0xD6	; Serial 1 Mode
.equ SER1_BAUD, 0xD7	; Serial 1 Baud Rate Control

; (Legacy aliases removed - now using primary names SER0_CR, SER0_MOD, etc.)

; Port F area (Serial I/O pins)
.equ PF_FC, 0xE5	; Port F Function Control

; Other Port Function Controls
.equ PORT_FC_1, 0xEC	; Port function control
.equ PORT_FC_2, 0xED	; Port function control
.equ PORT_FC_3, 0xF0	; Port function control
.equ PORT_FC_4, 0xF6	; Port function control

; ==============================================================================
; Extended SFR (0x0100+)
; ==============================================================================

; DMA/Interrupt Controller Area (0x100-0x10F)
.equ DMA_VECTOR, 0x102	; DMA interrupt vector/control

; Interrupt Controller (0x10A area)
.equ INT_CTRL, 0x10A	; Interrupt controller

; Watchdog Timer (0x110-0x111) - The REAL watchdog registers!
.equ WDMOD_REAL, 0x110	; Watchdog Mode Register
				; Bit 0-1: WDTP (Detection time)
				; Bit 4-5: HALTM (HALT mode)
				; Bit 6: DRVE (Drive enable in STOP)
				; Bit 7: WDTE (Watchdog enable)
.equ WDCR_REAL, 0x111	; Watchdog Control (write 4Eh to clear)

; Memory Controller - Block 0 (0x140-0x143)
.equ B0CSL, 0x140	; Block 0 Control Low (wait states)
.equ B0CSH, 0x141	; Block 0 Control High (bus width, mode)
.equ MAMR0, 0x142	; Block 0 Address Mask
.equ MSAR0, 0x143	; Block 0 Start Address

; Memory Controller - Block 1 (0x144-0x147)
.equ B1CSL, 0x144	; Block 1 Control Low
.equ B1CSH, 0x145	; Block 1 Control High
.equ MAMR1, 0x146	; Block 1 Address Mask
.equ MSAR1, 0x147	; Block 1 Start Address

; Memory Controller - Block 2 (0x148-0x14B)
.equ B2CSL, 0x148	; Block 2 Control Low
.equ B2CSH, 0x149	; Block 2 Control High
.equ MAMR2, 0x14A	; Block 2 Address Mask
.equ MSAR2, 0x14B	; Block 2 Start Address

; Memory Controller - Block 3 (0x14C-0x14F)
.equ B3CSL, 0x14C	; Block 3 Control Low
.equ B3CSH, 0x14D	; Block 3 Control High
.equ MAMR3, 0x14E	; Block 3 Address Mask
.equ MSAR3, 0x14F	; Block 3 Start Address

; Memory Controller - Block 4 (0x150-0x153)
.equ B4CSL, 0x150	; Block 4 Control Low
.equ B4CSH, 0x151	; Block 4 Control High
.equ MAMR4, 0x152	; Block 4 Address Mask
.equ MSAR4, 0x153	; Block 4 Start Address

; Memory Controller - Block 5 (0x154-0x157)
.equ B5CSL, 0x154	; Block 5 Control Low
.equ B5CSH, 0x155	; Block 5 Control High
.equ MAMR5, 0x156	; Block 5 Address Mask
.equ MSAR5, 0x157	; Block 5 Start Address

; DRAM Controller (0x160-0x167)
.equ DRAM_REFRESH, 0x162	; DRAM Refresh Control
.equ DRAM_CTRL, 0x163	; DRAM Controller Mode
.equ DRAM_TIMING1, 0x165	; DRAM Timing 1
.equ DRAM_TIMING2, 0x166	; DRAM Timing 2

; RAM variables - Communication and State
.equ SUBCPU_STATUS_FLAGS, 0x4FE	; Status flags (bit 6=payload ready, bit 7=xfer complete)
.equ DMA_TARGET_ADDR, 0x512	; Current DMA destination address (4 bytes)
; Note: DMA_XFER_STATE was here but is same address as DMA_XFER_STATE (0x0516)
.equ CMD_PROCESSING_STATE, 0x518	; Command processing state (0-4)
.equ LAST_CMD_BYTE, 0x51A	; Last received command byte from main CPU

; RAM variables - Data Buffers
.equ CMD_DATA_BUFFER, 0x51E	; Variable-length command data (32 bytes max)
.equ CMD_E1_BUFFER, 0x544	; E1 command data buffer (6 bytes)
.equ CMD_E2_BUFFER, 0x54A	; E2 command data buffer (10 bytes)

; RAM variables - Diagnostics
.equ MEMTEST_RESULT, 0x556	; Memory test result flags
.equ SERIAL_STATUS, 0x558	; Serial status bytes (8 bytes)

; ==============================================================================
; ROM starts with 96KB of 0xFF (erased flash)
; Actual data begins at 0xFF8000 (file offset 0x18000)
; ==============================================================================

	.org 0xFE0000 - 0xFE0000, 0xFF

	; Fill first 96KB with 0xFF
	.byte 0xff
	.byte 0xff
	.byte 0xff
	.byte 0xff
