	nop
	ld wa, (xbc + 4)	; Get param[4:5] again
	res 15, wa	; Clear bit 15 (was set earlier)
	stw_da (0x100002), xwa
	jr __jrt_nop_FF8F50
__jrt_nop_FF8F50:
	nop
	nop
	nop

	popw iz
	inc 4, xsp	; Release 4 bytes from stack
	ret

; ==============================================================================
; HARDWARE_VERIFY_WRITE (0xFF8F57) - Hardware write routine
;
; Writes WA to 0x100000, then IZ (from BC) to 0x100002.
; Simple write with timing delays (nops and jr T).
;
; Input: WA = value to write to 0x100000
;        BC = value to write to 0x100002
; ==============================================================================

	.org 0xFF8F57 - 0xFE0000, 0xFF

HARDWARE_VERIFY_WRITE:
	pushw iz
	ld iz, bc	; Save BC in IZ
	stw_da (0x100000), xwa; Write address/command
	nop
	stw_da (0x100002), xiz; Write data from IZ
	jr __jrt_nop_FF8F67	; Short delay
__jrt_nop_FF8F67:
	nop
	nop
	nop
	popw iz
	ret

; ==============================================================================
; Vector Trampoline Data (0xFF8F6C)
; This data gets copied to RAM at 0x0400 during boot.
; Each entry is: JP addr (4 bytes) + RET (1 byte) = 5 bytes per handler
; Total: 45 handlers x 5 bytes = 225 (0xE1) bytes
; ==============================================================================

	.org 0xFF8F6C - 0xFE0000, 0xFF

VECTOR_TRAMPOLINES:
	; Handler 0 - Reset/Main entry
	jp RESET_HANDLER	; Jump to ROM reset handler
	ret
	; Handler 1
	jp DEFAULT_HANDLER
	ret
	; Handler 2
	jp DEFAULT_HANDLER
	ret
	; Handler 3
	jp DEFAULT_HANDLER
	ret
	; Handler 4
	jp DEFAULT_HANDLER
	ret
	; Handler 5
	jp DEFAULT_HANDLER
	ret
	; Handler 6
	jp DEFAULT_HANDLER
	ret
	; Handler 7
	jp DEFAULT_HANDLER
	ret
	; Handler 8 - Uses RESET_ENTRY (software reset)
	jp RESET_ENTRY
	ret
	; Handler 9 - Serial Receive Interrupt (inter-CPU communication)
	jp InterCPU_RX_Handler
	ret
	; Handlers 10-35: Default (26 handlers)
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	; Handler 36 - Timer/Processing Interrupt (main work handler)
	jp CMD_Dispatch_Handler	; Note: Handler 36 uses CMD_Dispatch_Handler code
	ret
	; Handler 37 - Default
	jp DEFAULT_HANDLER
	ret
	; Handler 38 - DMA Complete Interrupt
	jp DMA_Complete_Handler	; Note: Handler 38 uses DMA_Complete_Handler code
	ret
	; Handlers 39-43: Default (5 handlers)
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	jp DEFAULT_HANDLER
	ret
	; Handler 44 - Error/Halt handler
	jp HALT_LOOP
	ret

; ==============================================================================
; Debug/Utility Routines (0xFFFE80 - 0xFFFED1)
;
; These appear to be debug or diagnostic routines, possibly for serial output.
; DEBUG_OUTPUT_BYTE_HEX: Wrapper that calls SUB_FEC1
; HEX_BYTE_TO_ASCII: Output hex byte (calls NIBBLE_TO_HEX_ASCII for nibble conversion, SUB_FEC1 for output)
; DEBUG_OUTPUT_STRING: Output null-terminated string from (XIX)
; NIBBLE_TO_HEX_ASCII: Convert nibble (0-15) to ASCII hex character ('0'-'9', 'a'-'f')
; SUB_FEC1: Output character (loads IZ with 0xFE00, placeholder NOPs)
; ==============================================================================

	.org 0xFFFE80 - 0xFE0000, 0xFF

DEBUG_OUTPUT_BYTE_HEX:
	push xiz
	calr SUB_FEC1
	pop xiz
	ret

HEX_BYTE_TO_ASCII:
	push xiz
	ld w, a	; Save A in W
	srl a, 4	; A >>= 4 (high nibble)
	calr NIBBLE_TO_HEX_ASCII	; Convert to hex char
	pushw wa
	calr SUB_FEC1	; Output character
	popw wa
	ld a, w	; Restore original A
	and a, 0xF	; Mask low nibble
	calr NIBBLE_TO_HEX_ASCII	; Convert to hex char
	calr SUB_FEC1	; Output character
	pop xiz
	ret

DEBUG_OUTPUT_STRING:
	push xiz
	ld xix, xwa	; XIX = string pointer
DEBUG_OUTPUT_STRING__loop:
	ldb_spi A, 0xF0	; Load next char, increment
	cps a, 0	; Check for null terminator
	jr z, DEBUG_OUTPUT_STRING__done	; If null, exit
	push xix
	calr SUB_FEC1	; Output character
	pop xix
	jr DEBUG_OUTPUT_STRING__loop	; Continue loop
DEBUG_OUTPUT_STRING__done:
	pop xiz
	ret

NIBBLE_TO_HEX_ASCII:
	cp a, 0xA	; Compare with 10
	jr nc, NIBBLE_TO_HEX_ASCII__letter	; If >= 10, use letter
	add a, 0x30	; '0' = 0x30
	ret
NIBBLE_TO_HEX_ASCII__letter:
	add a, 0x57	; 'a' - 10 = 0x57
	ret

SUB_FEC1:
	ldw iz, 0xFE00	; Output port address (placeholder)
	nop	; Timing/placeholder
	nop
	nop
	nop
	nop
	nop
	nop
	nop
	nop
	nop
	nop
	nop
	nop
	ret

; ==============================================================================
; Reserved area (0xFFFED2 - 0xFFFEDF)
; ==============================================================================

	.org 0xFFFED2 - 0xFE0000, 0xFF

	.fill 8, 1, 0xff	; 0xFFFED2-0xFFFED9
	.fill 6, 1, 0xff	; 0xFFFEDA-0xFFFEDF

; ==============================================================================
; Reset Handler (0xFFFEE0)
; This is the actual reset entry point, called from vector table
; ==============================================================================

	.org 0xFFFEE0 - 0xFE0000, 0xFF

RESET_HANDLER:
	jp BOOT_INIT	; Jump to main boot initialization
	ret	; Never reached

; ==============================================================================
; Reserved area (0xFFFEE5 - 0xFFFEEF)
; ==============================================================================

	.org 0xFFFEE5 - 0xFE0000, 0xFF

	.fill 9, 1, 0xff	; 0xFFFEE5-0xFFFEED
	.byte 0x00, 0x00	; 0xFFFEEE-0xFFFEEF

; ==============================================================================
; Reserved data area (0xFFFEF0 - 0xFFFEFF)
; Appears to be some kind of configuration or padding data
; ==============================================================================

	.org 0xFFFEF0 - 0xFE0000, 0xFF

	.byte 0x00, 0x04, 0x00, 0x00	; 0xFFFEF0-0xFFFEF3
	.byte 0x00, 0x04, 0x00, 0x00	; 0xFFFEF4-0xFFFEF7
	.byte 0x00, 0x04, 0x00, 0x00	; 0xFFFEF8-0xFFFEFB
	.byte 0x00, 0x04, 0x00, 0x00	; 0xFFFEFC-0xFFFEFF

; ==============================================================================
; Interrupt Vector Table (0xFFFF00 - 0xFFFFFF)
; 4-byte entries pointing to handlers in RAM at 0x04xx
; These addresses point to the trampolines copied to RAM
; ==============================================================================

	.org 0xFFFF00 - 0xFE0000, 0xFF

VECTOR_TABLE:
	.long 0xFFFEe0	; Reset - points to ROM handler at 0xFFFEE0
	.long 0x405	; Handler 1 at 0x0405
	.long 0x40A	; Handler 2 at 0x040A
	.long 0x40F	; Handler 3 at 0x040F
	.long 0x414	; Handler 4 at 0x0414
	.long 0x419	; Handler 5 at 0x0419
	.long 0x41E	; Handler 6 at 0x041E
	.long 0x423	; Handler 7 at 0x0423
	.long 0x4DC	; Handler 8 at 0x04DC (different!)
	.long 0x428	; Handler 9 at 0x0428
	.long 0x42D	; Handler 10
	.long 0x432	; Handler 11
	.long 0x437	; Handler 12
	.long 0x43C	; Handler 13
	.long 0x441	; Handler 14
	.long 0x446	; Handler 15
	.long 0x44B	; Handler 16
	.long 0x450	; Handler 17
	.long 0x455	; Handler 18
	.long 0x45A	; Handler 19
	.long 0x45F	; Handler 20
	.long 0x464	; Handler 21
	.long 0x469	; Handler 22
	.long 0x46E	; Handler 23
	.long 0x473	; Handler 24
	.long 0x478	; Handler 25
	.long 0x47D	; Handler 26
	.long 0x482	; Handler 27
	.long 0x487	; Handler 28
	.long 0x48C	; Handler 29
	.long 0x491	; Handler 30
	.long 0x496	; Handler 31
	.long 0x49B	; Handler 32
	.long 0x4A0	; Handler 33
	.long 0x4A5	; Handler 34
	.long 0x4AA	; Handler 35
	.long 0x4AF	; Handler 36
	.long 0x4B4	; Handler 37
	.long 0x4B9	; Handler 38
	.long 0x4BE	; Handler 39
	.long 0x4C3	; Handler 40
	.long 0x4C8	; Handler 41
	.long 0x4CD	; Handler 42
	.long 0x4D2	; Handler 43
	.long 0x4D7	; Handler 44
	; Fill rest with FF
	.byte 0xff, 0xff, 0xff, 0xff
	.byte 0xff, 0xff, 0xff, 0xff
	.byte 0xff, 0xff, 0xff, 0xff

	.org 0xFFFFF0 - 0xFE0000, 0xFF

RESET_VECTORS:
	; TMP94C241 reserved area (0xFFFFF0-0xFFFFFF)
	; Per datasheet: "Do not use" / reserved for system configuration
	; Pattern 41 B1 62 1B repeated 4 times - may be factory calibration data
	; or ROM identification/checksum (not part of interrupt vector table)
	.byte 0x41, 0xb1, 0x62, 0x1b
	.byte 0x41, 0xb1, 0x62, 0x1b
	.byte 0x41, 0xb1, 0x62, 0x1b
	.byte 0x41, 0xb1, 0x62, 0x1b

end:
